export interface Staging {
  light: Light;
  line: string;
  /** Another brief showing the same place: its generated image, when it exists, joins the references. */
  samePlaceAs?: string;
  /** An interior open onto the sky (the Dragon's halls): the indoors rule against sky and daylight does not apply. */
  skyVisible?: boolean;
  /**
   * The Arena of Destinies during the Tournament: a distant, indistinct crowd in the stands only, never a figure on the
   * ground or in the foreground (the final act's staging, validated as is by the operator on 2026-11-12).
   */
  crowd?: boolean;
}

